import csv
import sys


def rows(path):
    with open(path, newline="") as f:
        return [(r["date"], round(float(r["amount"]), 2), r.get("memo", "")) for r in csv.DictReader(f)]


bank, books = rows(sys.argv[1]), rows(sys.argv[2])
booked = {(d, a) for d, a, _ in books}
for date, amount, memo in bank:
    if (date, amount) not in booked and abs(amount) > 1:
        print(f"{date}\t{amount:.2f}\t{memo}")
